typedef float vm_num_t;

class stringx;
class script_instance {
public:
  const stringx& get_name() const;
};
class script_executable {
public:
  const stringx& get_fullname() const;
};
class vm_thread {
public:
  script_instance* get_instance() const;
  script_executable* get_executable() const;
};
class vm_stack {
public:
  int salloc;
  char* buffer;
  char* SP;
private:
  vm_thread* my_thread;
public:
  char* get_SP() const { return SP; }
  void pop(int n) { SP -= n; }
  vm_thread* get_thread() const { return my_thread; }
  bool push(const char* src, int n);
};
class stringx {
public:
  stringx();
  stringx(const stringx&);
  ~stringx();
};
stringx operator+(const stringx&, const char*);
stringx operator+(const stringx&, const stringx&);
void error(const stringx&);

class script_library_class {
public:
  class function {
  public:
    enum entry_t { FIRST_ENTRY, RECALL_ENTRY };
  protected:
    char* name;
  public:
    virtual bool operator()(vm_stack&, entry_t) { return true; }
  };
};

class vector3d {
public:
  typedef float T;
  T x, y, z;
  inline vector3d() {}
  inline vector3d(T _x, T _y, T _z) { x = _x; y = _y; z = _z; }
};
inline vector3d operator/(const vector3d& a, vector3d::T d)
{
  return vector3d(a.x / d, a.y / d, a.z / d);
}

#define SLF_PARMS \
  stack.pop(sizeof(parms_t)); \
  parms_t* parms = (parms_t*)stack.get_SP()
#define SLF_RETURN \
  if (!stack.push((char*)&result,sizeof(result)) ) \
    error( stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname() )
#define SLF_DONE return true

class slf_vector3d_div_scalar_t : public script_library_class::function
{
public:
  struct parms_t
  {
    vector3d me;
    vm_num_t s;
  };
  virtual bool operator()(vm_stack& stack,entry_t entry);
};

bool slf_vector3d_div_scalar_t::operator()(vm_stack& stack,entry_t entry)
{
  SLF_PARMS;
  vector3d result = parms->me / parms->s;
  SLF_RETURN;
  SLF_DONE;
}
